//! `packs/std/generated/*.rs`: the std GRL rules compiled to Rust modules (plugins.md 6.1).
//!
//! Never a build script: the modules are checked in, regenerated by `cargo dev gen std-rules` and
//! byte-compared by GEN001. Each module forbids `unsafe` and sits under a grimble node that holds
//! no grants (`design/model.grmb`), so any ambient effect in it is CAP001.

// frob:ticket 01M3ZX7HN0YF3SYGVJRT5H07H5
use std::path::{Path, PathBuf};

use gob_plan::lower::{SourceError, lower_source};

use super::marker_text;
use crate::files::GenFile;

/// Where the std GRL sources live, relative to the workspace root.
pub const SOURCE_DIR: &str = "packs/std/rules";
/// Where the generated modules are written, relative to the workspace root.
pub const OUT_DIR: &str = "packs/std/generated";

/// Why the std rule modules could not be generated.
#[derive(Debug, thiserror::Error)]
pub enum StdRulesError {
    /// A source directory or file could not be read.
    #[error("read {}: {source}", gob_path::Shown::with_home(path, None))]
    Io {
        /// The path.
        path: PathBuf,
        /// Underlying error.
        source: std::io::Error,
    },
    /// A source did not parse or lower.
    #[error("{path}: {source}")]
    Source {
        /// The source path, relative to the root.
        path: String,
        /// Why it failed.
        source: SourceError,
    },
}

/// The `.grl` files directly under `dir`, sorted by name; none when the directory is absent.
fn sources(dir: &Path) -> Result<Vec<PathBuf>, StdRulesError> {
    let io = |source| StdRulesError::Io {
        path: dir.to_path_buf(),
        source,
    };
    let entries = match std::fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(e) => return Err(io(e)),
    };
    let mut out = Vec::new();
    for entry in entries {
        let path = entry.map_err(io)?.path();
        if path.extension().is_some_and(|e| e == "grl") {
            out.push(path);
        }
    }
    out.sort();
    Ok(out)
}

/// One generated module per std rule found under `<root>/packs/std/rules`, each led by the GEN001 marker.
///
/// # Errors
/// [`StdRulesError`] when a source cannot be read, parsed or lowered.
pub fn generate(root: &Path) -> Result<Vec<GenFile>, StdRulesError> {
    let mut files = Vec::new();
    for path in sources(&root.join(SOURCE_DIR))? {
        let rel = format!(
            "{SOURCE_DIR}/{}",
            path.file_name()
                .map_or_else(String::new, |n| gob_path::Shown::with_home(
                    std::path::Path::new(&n),
                    None
                )
                .to_string())
        );
        let text = std::fs::read_to_string(&path).map_err(|source| StdRulesError::Io {
            path: path.clone(),
            source,
        })?;
        let plans = lower_source(&rel, &text).map_err(|source| StdRulesError::Source {
            path: rel.clone(),
            source,
        })?;
        for plan in plans {
            let content = format!(
                "// {}\n{}",
                marker_text("std-rules"),
                gob_plan::codegen::generate(&plan)
            );
            files.push(GenFile {
                path: format!("{OUT_DIR}/{}.rs", plan.rule().to_ascii_lowercase()),
                content,
            });
        }
    }
    tracing::debug!(files = files.len(), "generated std rule modules");
    Ok(files)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::files::{Mode, apply};

    const RULE: &str = "rule STD001 \"std-demo\" {\n  lang typescript\n  severity error\n  find c: call where c.callee == \"danger\"\n  report c \"danger\"\n  explain \"\"\"\n    Danger.\n\n    ## Remedy\n    Do not.\n  \"\"\"\n}\n";

    fn root_with(source: &str) -> tempfile::TempDir {
        let dir = tempfile::tempdir().unwrap();
        let src = dir.path().join(SOURCE_DIR);
        std::fs::create_dir_all(&src).unwrap();
        std::fs::write(src.join("STD001.grl"), source).unwrap();
        dir
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate
    #[test]
    fn a_changed_source_is_reported_stale_by_check_mode() {
        let dir = root_with(RULE);
        let files = generate(dir.path()).unwrap();
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].path, "packs/std/generated/std001.rs");
        apply(dir.path(), &files, Mode::Write).unwrap();
        let clean = apply(dir.path(), &generate(dir.path()).unwrap(), Mode::Check).unwrap();
        assert_eq!(clean.differing, 0);
        assert_eq!(clean.marker_problems, 0);
        let edited = RULE.replace("danger", "peril");
        std::fs::write(dir.path().join(SOURCE_DIR).join("STD001.grl"), edited).unwrap();
        let stale = apply(dir.path(), &generate(dir.path()).unwrap(), Mode::Check).unwrap();
        assert_eq!(
            stale.differing, 1,
            "GEN001 must flag the regenerated module"
        );
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate
    #[test]
    fn a_generated_module_forbids_unsafe_and_touches_no_ambient_effect() {
        let dir = root_with(RULE);
        let text = &generate(dir.path()).unwrap()[0].content;
        assert!(text.contains("#![forbid(unsafe_code)]"));
        for ambient in [
            "std::fs",
            "std::process",
            "std::net",
            "std::env",
            "unsafe {",
        ] {
            assert!(!text.contains(ambient), "ambient effect `{ambient}`");
        }
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate
    #[test]
    fn a_broken_source_fails_generation() {
        let dir = root_with("rule {");
        assert!(matches!(
            generate(dir.path()),
            Err(StdRulesError::Source { .. })
        ));
    }

    // frob:tests crates/gob-dev/src/render/std_rules.rs::generate
    #[test]
    fn the_generated_tree_has_no_grants_in_the_model() {
        let model = include_str!("../../../../design/model.grmb");
        let node = model
            .split("node std_rules")
            .nth(1)
            .and_then(|rest| rest.split("\n}\n").next())
            .expect("node std_rules in design/model.grmb");
        assert!(node.contains("owns \"packs/std/generated/**\""));
        assert!(
            !node.contains("may "),
            "the generated std node must hold no grants"
        );
    }
}
